import{bQ as e,aL as d,u as s,G as a}from"./chunks/framework.D06dwy5q.js";const c=JSON.parse('{"title":"01｜认识 Redis：是什么、和 Valkey 的关系","description":"","frontmatter":{},"headers":[],"relativePath":"05.Redis/01-认识Redis.md","filePath":"05.Redis/01-认识Redis.md","lastUpdated":null}'),r={name:"05.Redis/01-认识Redis.md"};function i(o,t,l,n,p,R){return d(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="_01-认识-redis-是什么、和-valkey-的关系" tabindex="-1">01｜认识 Redis：是什么、和 Valkey 的关系 <a class="header-anchor" href="#_01-认识-redis-是什么、和-valkey-的关系" aria-label="Permalink to &quot;01｜认识 Redis：是什么、和 Valkey 的关系&quot;">​</a></h1><p>Redis 是一个内存型的键值存储。数据放在内存里，不走磁盘，单次读写在微秒级，比磁盘数据库快三四个数量级。代价是容量受内存限制——一台机器能存几十 GB 就到头了，磁盘能存几 TB。所以 Redis 和 MySQL 不替代，是配合：MySQL 存全量数据，Redis 存热数据缓存。</p><p>存储方式很简单：一个 key 对应一个 value。<code>SET user:1 &quot;zhangsan&quot;</code> 存进去，<code>GET user:1</code> 取出来。值可以是简单文本，也可以是列表、哈希、集合等复杂结构。后面几篇会逐个展开。</p><table tabindex="0"><thead><tr><th>维度</th><th>Redis</th><th>MySQL</th></tr></thead><tbody><tr><td>存放位置</td><td>内存</td><td>磁盘</td></tr><tr><td>单次读写</td><td>微秒级</td><td>毫秒级</td></tr><tr><td>数据量</td><td>受内存限制（GB 级）</td><td>受磁盘限制（TB 级）</td></tr><tr><td>持久化</td><td>可选（RDB/AOF）</td><td>默认持久</td></tr><tr><td>典型用途</td><td>缓存、计数、队列</td><td>业务数据存储</td></tr></tbody></table><h2 id="一、为什么快" tabindex="-1">一、为什么快 <a class="header-anchor" href="#一、为什么快" aria-label="Permalink to &quot;一、为什么快&quot;">​</a></h2><p>三个原因，理解这些有助于后面调优：</p><p><strong>全内存</strong>——磁盘是最大的慢因素，Redis 跳过了它。内存读写比磁盘快几个数量级，这是速度的根本来源。</p><p><strong>单线程处理命令</strong>——Redis 核心的命令处理是单线程的，不用锁、不用线程切换。听起来单线程慢，但单线程跑内存操作比多线程跑磁盘快得多。多线程的优势在 CPU 密集场景，Redis 是 I/O 密集（内存 I/O），单线程足够。</p><p><strong>I/O 多路复用</strong>——一个线程同时处理很多连接，靠操作系统提供的 epoll 机制，哪个连接有数据就处理哪个。不用为每个连接开一个线程，连接数成千上万也不会把系统拖垮。</p><p>后面性能调优篇会展开，这里先建立&quot;内存 + 单线程 + 多路复用&quot;这个基本认知。</p><h2 id="二、redis-和-valkey-的关系" tabindex="-1">二、Redis 和 Valkey 的关系 <a class="header-anchor" href="#二、redis-和-valkey-的关系" aria-label="Permalink to &quot;二、Redis 和 Valkey 的关系&quot;">​</a></h2><p>这是 2024 年后学 Redis 必须搞清的事。</p><p><strong>2024 年 3 月之前</strong>：Redis 一直是开源的（BSD 许可证），社区和云厂商都基于它做产品。</p><p><strong>2024 年 3 月</strong>：Redis 公司把 Redis 7.4 之后的许可证从 BSD 改成了 SSPL 和 RSALv2。这俩限制了云厂商把 Redis 当托管服务对外提供。AWS、Google 这些云厂商没法继续用了。</p><p><strong>几天后</strong>：社区从 Redis 7.2.4 fork 出 Valkey，交给 Linux Foundation 维护，继续走 BSD 开源。Valkey 起源就是 Redis 7.2.4，命令、协议、数据格式都和 Redis 7.2 一样。</p><p>分叉之后两家各自发展：</p><ul><li><strong>Redis</strong>：Redis 8（2025.5）改用三许可（含 AGPLv3），加了很多新特性（JSON、向量搜索等），品牌还是 Redis</li><li><strong>Valkey</strong>：8.x/9.x，BSD 开源，加多线程 I/O、大规模集群支持，云厂商（AWS ElastiCache 等）大量转向 Valkey</li></ul><p>实际影响：</p><table tabindex="0"><thead><tr><th>方面</th><th>说明</th></tr></thead><tbody><tr><td>命令和协议</td><td>两家基本通用，都是 RESP 协议。客户端代码大多不用改</td></tr><tr><td>数据文件</td><td>Redis 7.4+ 的 RDB 和 Valkey 不兼容。Redis 7.2 的 RDB 两边都能读</td></tr><tr><td>选哪个</td><td>新项目和云环境多选 Valkey（开源、云厂商支持）；存量项目多还在 Redis</td></tr><tr><td>教程</td><td>本系列命令以 RESP 协议为准，两家通用</td></tr></tbody></table><p>&quot;用 Redis 还是 Valkey&quot;在命令层面不重要，学一套两边都能用。涉及高级特性（8.x 的新数据结构）才开始分叉，本系列主线讲 7.2/7.4 共通的部分。</p><h2 id="三、redis-用在哪些场景" tabindex="-1">三、Redis 用在哪些场景 <a class="header-anchor" href="#三、redis-用在哪些场景" aria-label="Permalink to &quot;三、Redis 用在哪些场景&quot;">​</a></h2><p>理解这些场景，后面学数据类型时知道每种结构为什么这么设计：</p><p><strong>缓存</strong>——最常见。数据库查询结果放 Redis，应用先查 Redis 命中就不用查数据库。string 类型就够用。</p><p><strong>计数器</strong>——文章阅读量、API 调用次数。Redis 的 <code>INCR</code> 原子自增，string 类型。</p><p><strong>排行榜</strong>——游戏积分排行、热帖排序。用 zset（有序集合），按分数排序天然支持。</p><p><strong>消息队列</strong>——异步任务、解耦。list 或 stream，生产者推、消费者拉。</p><p><strong>会话存储</strong>——用户登录态。分布式 session 放 Redis，多台应用共享。</p><p><strong>限流</strong>——接口防刷。计数器加过期时间实现。</p><h2 id="四、一个必须知道的坑-公网暴露" tabindex="-1">四、一个必须知道的坑：公网暴露 <a class="header-anchor" href="#四、一个必须知道的坑-公网暴露" aria-label="Permalink to &quot;四、一个必须知道的坑：公网暴露&quot;">​</a></h2><p>Redis 默认监听 <code>127.0.0.1</code>，只接受本机连接。但有人为了方便改成 <code>bind 0.0.0.0</code> 或者安全组放得太宽，把 6379 端口暴露到了公网——这是一个已经反复发生过的攻击路径。</p><p>攻击者连上无密码的 Redis 后，利用 <code>CONFIG SET dir</code> 和 <code>CONFIG SET dbfilename</code> 把 RDB 文件写到 <code>/root/.ssh/authorized_keys</code>，写入自己的 SSH 公钥，然后直接 SSH 登录服务器。Redis 本身没有文件系统沙箱，写目录和写文件名都能通过命令改。</p><p>防护措施在 <a href="/kb/05.Redis/11-安全配置">安全配置</a> 里讲，但核心原则在这里先建立：</p><ul><li>生产环境 Redis 绝不监听 <code>0.0.0.0</code></li><li><code>bind</code> 只绑内网地址</li><li>必须设密码或 ACL</li><li>前面有防火墙或安全组严格限制来源</li></ul><h2 id="五、本系列的内容路线" tabindex="-1">五、本系列的内容路线 <a class="header-anchor" href="#五、本系列的内容路线" aria-label="Permalink to &quot;五、本系列的内容路线&quot;">​</a></h2><p>后面 11 篇依次讲：安装连接（02）、数据类型（03、04）、过期和内存（05）、持久化（06）、性能（07）、主从和哨兵（08、09）、Cluster（10）、安全（11）、监控运维（12）。</p><p>学完能独立操作和运维一套 Redis——从单机缓存到集群高可用，从日常监控到故障排查。</p>',36)])])}const u=e(r,[["render",i]]);export{c as __pageData,u as default};
